import{c as t,Q as a,j as r,m as i}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Not All Tokens Are Worth Caching: Learning Semantic-Aware Eviction for LLM Prefix Caches","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.18825","title":"Not All Tokens Are Worth Caching: Learning Semantic-Aware Eviction for LLM Prefix Caches","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2605.18825,"authors":["Shaoke Fang","Ziang Li","Wenfei Wu","Jiatong Ji","Qingsong Liu","Ruizhi Pu"],"domains":["cs.LG","prompt caching"],"html":"https://arxiv.org/html/2605.18825v1","pdf_path":"pdfs/2605.18825.pdf","published_date":"2026-05-12T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-12-saecache-semantic-aware-prefix-cache-eviction-2605-18825.md","filePath":"research/papers/2026-05-12-saecache-semantic-aware-prefix-cache-eviction-2605-18825.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-05-12-saecache-semantic-aware-prefix-cache-eviction-2605-18825.md"};function n(s,e,l,c,h,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="not-all-tokens-are-worth-caching-learning-semantic-aware-eviction-for-llm-prefix-caches" tabindex="-1">Not All Tokens Are Worth Caching: Learning Semantic-Aware Eviction for LLM Prefix Caches <a class="header-anchor" href="#not-all-tokens-are-worth-caching-learning-semantic-aware-eviction-for-llm-prefix-caches" aria-label="Permalink to &quot;Not All Tokens Are Worth Caching: Learning Semantic-Aware Eviction for LLM Prefix Caches&quot;">​</a></h1><p><strong>Authors</strong>: Shaoke Fang, Ziang Li, Wenfei Wu, Jiatong Ji, Qingsong Liu, Ruizhi Pu <strong>Published</strong>: May 12, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.18825" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.18825</a> · <a href="https://arxiv.org/html/2605.18825v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2605.18825 <strong>Categories</strong>: cs.LG, prompt caching <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.18825" target="_blank" rel="noreferrer">research/papers/pdfs/2605.18825.pdf</a> (31 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Prefix caching is a key optimization in Large Language Model (LLM) serving, reusing attention Key-Value (KV) states across requests with shared prompt prefixes to reduce expensive prefill computation. However, its benefit depends critically on the eviction policy as GPU memory is scarce, and existing policies such as LRU largely treat cached blocks uniformly. This view ignores a fundamental property of LLM prompts: not all tokens are equally worth caching. We show that different token types within a prompt, including system prompts, user queries, tool outputs, model responses, and chain-of-thought reasoning, exhibit up to 756x variation in reuse rates, yet no existing eviction policy exploits this signal. In this paper, we present SAECache (Semantic-Adaptive Eviction for prefix caches), a semantic-adaptive prefix cache eviction policy that addresses this gap through three innovations: (1) a multi-queue architecture that routes KV blocks to task-specific queues with tailored priority metrics, capturing both session reuse in multi-turn requests and structural reuse in templated single-turn requests; (2) a semantic-aware token weighting mechanism that learns the reuse value of different token types online through eviction feedback; (3) a fully adaptive online learning schema for all parameter updates, including log-normal timing parameters, position decay power, queue weights, and meta-parameters, which eliminates manual tuning and enables automatic adaptation to deployment-specific workload characteristics. Through extensive evaluation across heterogeneous workloads, we demonstrate that SAECache achieves 1.4x-2.7x TTFT improvement over production-style baselines, while fixed-parameter alternatives can degrade by up to 2.7x under workload mismatch -- a failure mode our adaptive approach avoids entirely.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li><strong>Reuse rate 差異揭露</strong>：實證不同 token 類型（system prompt、user query、tool output、model response、chain-of-thought）的 KV block reuse rate 相差最高 756x，打破 LRU 等均等對待的假設。</li><li><strong>SAECache 三層設計</strong>：(1) multi-queue 架構依 token 類型路由 KV block，同時捕捉 multi-turn session reuse 與 single-turn structural reuse；(2) semantic-aware token weighting，透過 eviction feedback 線上學習各 token 類型的 reuse value；(3) 全參數 fully adaptive online learning（含 log-normal timing、position decay power、queue weights、meta-parameters），消除人工調參。</li><li><strong>部署自適應</strong>：所有參數線上更新，可自動適應 workload 分布漂移，不需重新調參。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>相較 production-style baselines，SAECache 達到 <strong>1.4x–2.7x TTFT（Time To First Token）改善</strong>。</li><li>固定參數替代方案在 workload mismatch 下最多降退 <strong>2.7x</strong>，而 SAECache 全適應設計完全迴避此失敗模式。</li><li>評估橫跨 heterogeneous workloads（multi-turn、templated single-turn 等多種場景）。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文自述限制未在 abstract 中明列；推測弱點： <ul><li>Online learning 的收斂速度與 cold-start 行為在 workload 急劇變化時可能存在延遲。</li><li>multi-queue 架構的 overhead（記憶體管理、queue routing）在小規模部署下的 cost-benefit 需實驗驗證。</li><li>評估場景以 LLM serving infrastructure 為主，edge 或 consumer 設備上的適用性未討論。</li></ul></li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>context-management.md — Prompt Caching 核心原則</strong>：SAECache 的核心發現（system prompt reuse rate 遠高於 user query）直接支持 workspace 規則「CLAUDE.md 內容 = 最穩定快取前綴，永遠放最前」——本論文提供了這一設計決策的實證基礎，並量化了不同 token 類型的 reuse value 差異（最高 756x）。</li><li><strong>NLAH 原則（Right context &gt; more context）</strong>：SAECache 的 semantic-aware weighting 與 NLAH 精神一致——並非所有 context 等價，高 reuse value 的 token（穩定 system prompt）應優先保留，低 reuse 的動態 user query 可優先 evict。</li><li><strong>跨切紀律「判斷 vs 決定」</strong>：SAECache 的 online learning schema 示範了一種在 LLM serving 層做「決定」（哪個 block evict）而非讓 LLM 做「判斷」的架構分離——與 workspace 核心紀律的精神對應；⚠️ 直接移植到 prompt 組裝層需額外橋接。</li><li><strong><code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md） — Fan-out token budget</strong>：SAECache 的 multi-queue 設計（依 token 角色分流）啟發 multi-agent 工作流中按 token 類型（system context vs tool output vs model response）差異化管理 context 配額的可能；⚠️ 目前 workspace 無對應實作，屬概念延伸。</li></ul>',16)])])}const d=t(o,[["render",n]]);export{g as __pageData,d as default};
